export interface CreateConfigurableLogDrainParams {
  deliveryFormat: "json" | "ndjson" | (string & {});
  url: string;
  sources: ("static" | "lambda" | "build" | "edge" | "external" | "firewall" | (string & {}))[];
  teamId?: string;
  slug?: string;
  headers?: { [key: string]: string };
  projectIds?: string[];
  environments?: ("preview" | "production" | (string & {}))[];
  secret?: string;
  samplingRate?: number;
  name?: string;
}

/**
 * Creates a configurable log drain for the authenticated team. Supply `deliveryFormat`, `url`, and `sources`; use the remaining fields to select projects, environments, headers, and sampling behavior. Call this deprecated operation with a team AccessToken, not an integration OAuth2 client.
 *
 * Creates a configurable log drain. This endpoint must be called with a team AccessToken (integration OAuth2 clients are not allowed)
 *
 * @param deliveryFormat - The delivery log format
 * @param url - The log drain url
 * @param teamId - The Team identifier to perform the request on behalf of.
 * @param slug - The Team slug to perform the request on behalf of.
 * @param headers - Headers to be sent together with the request
 * @param secret - Custom secret of log drain
 * @param samplingRate - The sampling rate for this log drain. It should be a
 *   percentage rate between 0 and 100. With max 2 decimal points
 * @param name - The custom name of this log drain.
 */
export async function createConfigurableLogDrain(
  config: ClientConfig,
  {
    deliveryFormat,
    url,
    sources,
    teamId,
    slug,
    headers,
    projectIds,
    environments,
    secret,
    samplingRate,
    name,
  }: CreateConfigurableLogDrainParams,
  requestOptions?: RequestOptions,
): Promise<{ [key: string]: unknown }> {
  validatePattern("url", url, "^(http|https)?://");
  validateUri("url", url);

  validateItems("sources", sources, { min: 1 });

  if (projectIds != null) {
    validateItems("projectIds", projectIds, { min: 1, max: 50 });
  }

  if (environments != null) {
    validateItems("environments", environments, { min: 1 });
  }

  if (samplingRate != null) {
    validateRange("samplingRate", samplingRate, { min: 0.01, max: 1, multipleOf: 0.01 });
  }

  const _resp = await sdkRequest<{ [key: string]: unknown }>({
    method: "POST",
    path: `/v1/log-drains`,
    operationId: "createConfigurableLogDrain",
    responseDecoder: "json",
    ...requestOptions,
    query: {
      teamId: queryValue("teamId", teamId, "form", true),
      slug: queryValue("slug", slug, "form", true),
    },
    body: {
      deliveryFormat,
      url,
      sources,
      headers,
      projectIds,
      environments,
      secret,
      samplingRate,
      name,
    },
    config,
  });
  return _resp.data;
}
